import numpy as np
import scipy.stats as st

def close(a, b, rtol: float = 1e-9) -> bool:
    x = np.asarray(a).astype(float).ravel()
    y = np.asarray(b).astype(float).ravel()
    if x.shape != y.shape:
        return False
    for i in range(x.shape[0]):
        u = float(x[i])
        v = float(y[i])
        if not (abs(u - v) <= 1e-10 + rtol * abs(v) or (u != u and v != v)):
            print('mismatch', i, u, v)
            return False
    return True

x = np.array([[0.3, -1.0, 2.0], [1.5, 0.2, -0.7]])

@test
def test_cov_prec():
    c = st.Covariance.from_precision(np.array([[0.5486381322957199, -0.17120622568093385, -0.058365758754863814], [-0.17120622568093385, 0.7626459143968872, -0.19455252918287938], [-0.058365758754863814, -0.19455252918287938, 1.0700389105058365]]))
    assert close(c.whiten(x), [0.2957551235087177, -1.3474430737064302, 2.0, 1.119982101812764, 0.34528228763727276, -0.7])
    assert close(c.colorize(x), [0.43447482475776783, -0.5874342087037918, 2.0, 1.9592177191890345, 0.027486841740758394, -0.7])
    assert close(c.log_pdet(), 0.9439058989071283)
    assert c.rank() == 3
    assert close(c.covariance(), [1.9999999999999998, 0.49999999999999994, 0.19999999999999998, 0.49999999999999994, 1.5, 0.29999999999999993, 0.2, 0.29999999999999993, 1.0])

@test
def test_cov_chol():
    c = st.Covariance.from_cholesky(np.array([[1.4142135623730951, 0.0, 0.0], [0.35355339059327373, 1.1726039399558574, 0.0], [0.1414213562373095, 0.21320071635561041, 0.966718911858796]]))
    assert close(c.whiten(x), [0.21213203435596423, -0.9167630803291248, 2.2400043268946033, 1.0606601717798212, -0.14924050144892723, -0.846349241899724])
    assert close(c.colorize(x), [0.4242640687119285, -1.0665379227778753, 1.7626635142331744, 2.121320343559643, 0.7648508738810821, -0.4219310606740708])
    assert close(c.log_pdet(), 0.9439058989071286)
    assert c.rank() == 3
    assert close(c.covariance(), [2.0000000000000004, 0.5, 0.2, 0.5, 1.5, 0.3, 0.2, 0.3, 1.0])

@test
def test_cov_eig():
    c = st.Covariance.from_eigendecomposition((np.array([0.8582463426785717, 1.2542074519639232, 2.387546205357504]), np.array([[0.040042476322141356, -0.5829127806019301, -0.8115474664496941], [-0.4485761488185466, 0.7152643622901071, -0.5358883566087689], [0.8928471531013088, 0.3854991339142703, -0.232839813928451]])))
    assert close(c.whiten(x), [2.424702877840241, -0.1063831014037675, -0.11212724865107962, -0.7066421807462469, -0.8939665531745048, -0.7517049931538634])
    assert close(c.colorize(x), [-1.8440144304121948, -2.5817808112787914, -0.9031351322915202, 0.8028659375557322, 0.11648136091399704, 1.5789105701726425])
    assert close(c.log_pdet(), 0.9439058989071274)
    assert c.rank() == 3
    assert close(c.covariance(), [2.0000000000000013, 0.5000000000000001, 0.20000000000000012, 0.5000000000000002, 1.499999999999998, 0.29999999999999966, 0.20000000000000012, 0.2999999999999996, 1.0])

@test
def test_cov_diag():
    c = st.Covariance.from_diagonal(np.array([1.0, 2.0, 0.5]))
    assert close(c.whiten(x), [0.3, -0.7071067811865475, 2.82842712474619, 1.5, 0.1414213562373095, -0.9899494936611664])
    assert close(c.colorize(x), [0.3, -1.4142135623730951, 1.4142135623730951, 1.5, 0.28284271247461906, -0.4949747468305833])
    assert close(c.log_pdet(), 0.0)
    assert c.rank() == 3
    assert close(c.covariance(), [1.0, 0.0, 0.0, 0.0, 2.0, 0.0, 0.0, 0.0, 0.5])

